// Finance cannot split a single payment across two invoices: parseInvoice
// settles each payment in full against the first invoice it matches.
export function parseInvoice(payment: Payment): Invoice { return settleInFull(payment) }

// A payment that could not split across two invoices is left on the
// reconciliation queue for two people to settle by hand.
export function reconcile(invoices: Invoice[]) { return invoices.filter((i) => !i.settled) }
